import { parseQuery } from "./queryparser";

function expectEqual(actual: unknown, expected: unknown, label: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    throw new Error(`${label}: got ${a}, want ${e}`);
  }
}

expectEqual(parseQuery("a=1&b=2"), { a: "1", b: "2" }, "basic multi-pair");
expectEqual(parseQuery("name=John%20Doe"), { name: "John Doe" }, "url-encoded value");
expectEqual(parseQuery("a=1&a=2"), { a: "2" }, "duplicate key: last wins");
expectEqual(parseQuery("?a=1"), { a: "1" }, "leading question mark stripped");
expectEqual(parseQuery("flag"), { flag: "" }, "key with no value");

console.log("all tests passed");

