import { parseQuery } from "./queryparser";

function expectTrue(cond: boolean, label: string): void {
  if (!cond) throw new Error(label);
}

expectTrue(typeof parseQuery("a=1") === "object", "returns object");
expectTrue(Object.keys(parseQuery("")).length === 0, "empty is empty");
expectTrue("a" in parseQuery("a=1&b=2"), "has key a");
expectTrue("b" in parseQuery("a=1&b=2"), "has key b");

console.log("all tests passed");
